//! BUTTON formAction reflects its actual submitter override without navigation.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form method=post action=https://button-action.test/default><input id=area name=q value=Seed><button id=submit type=submit name=go value=sent>Send</button><button id=reset type=reset>Reset</button></form><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://button-action.test/source?old=1#frag",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn button_form_action_canonical_fallback_scalar_and_once_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('submit'),a=Object.getOwnPropertyDescriptor(HTMLButtonElement.prototype,'formAction');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get formAction'||a.set.name!=='set formAction'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'formAction')||x.formAction!=='https://button-action.test/source?old=1#frag')throw 'canonical';x.formAction='';if(x.formAction!=='https://button-action.test/source?old=1#frag')throw 'empty fallback';var calls=0;x.formAction={toString:function(){calls++;return '../send?x=1#f';},valueOf:function(){throw 'hint';}};if(calls!==1||x.formAction!=='https://button-action.test/send?x=1#f'||x.getAttributeNS(null,'formaction')!=='../send?x=1#f')throw 'relative';x.formAction='A\ud800Z';if(x.getAttributeNS(null,'formaction')!=='A\ufffdZ'||x.formAction!=='https://button-action.test/A%EF%BF%BDZ')throw 'scalar setter';x.setAttribute('formaction','https://[\ud800');if(x.formAction!=='https://[\ufffd'||x.getAttributeNS(null,'formaction')!=='https://[\ud800')throw 'scalar getter';"#);}
#[test]
fn button_form_action_base_url_and_all_native_button_types(){let(mut d,mut f,mut p)=fixture();p.set_resource_base(&crate::navigation::address("https://other-button-action.test/base/",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"var x=document.getElementById('submit'),text=document.getElementById('reset');if(x.formAction!=='https://button-action.test/source?old=1#frag')throw 'document fallback';x.formAction='send';text.formAction='text';if(x.formAction!=='https://other-button-action.test/base/send'||text.formAction!=='https://other-button-action.test/base/text'||document.getElementById('area').value!=='Seed')throw 'live base and reset button';");}
#[test]
fn button_form_action_inert_exact_namespace_and_copies(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','button');x.setAttributeNS('urn:foreign','formaction','https://foreign.test/');x.setAttributeNS(null,'FORMACTION','https://upper.test/');if(x.formAction!=='about:blank')throw 'namespace';x.formAction='https://inert-button.test/one';var y=x.cloneNode(false);y.formAction='https://inert-button.test/two';if(x.formAction!=='https://inert-button.test/one'||y.formAction!=='https://inert-button.test/two')throw 'independent copy';x.formAction='';if(x.formAction!=='about:blank')throw 'empty';");}

#[test]
fn button_form_action_saved_child_origin_precedes_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('submit'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLButtonElement.prototype,'formAction'),calls=0;if(a.get.call(x)!=='https://button-action.test/source?old=1#frag')throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-button-action.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'https://button-action.test/get';}});"]{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://button-action.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin converted';a.set.call(x,'https://button-action.test/get');if(x.formAction!=='https://button-action.test/get')throw 'fresh recovery';");}

#[test]
fn button_form_action_resource_refusal_is_atomic_and_fresh_job_recovers(){for getter in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('submit');x.formAction='https://button-action.test/post';");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("form")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let string_limit=p.state.limits.host.string_bytes;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2 if !getter=>p.state.retained_limit=p.state.retained,2=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if getter{bridge.button_form_action_get(object).map(|_|())}else{bridge.button_form_action_set(object,&Value::String("https://button-action.test/longer-growing-value-than-the-existing-content-attribute".into()))};assert!(result.is_err(),"getter {getter} mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.limits.host.string_bytes=string_limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.formAction='https://button-action.test/get';if(x.formAction!=='https://button-action.test/get'||document.getElementById('area').value!=='Seed')throw 'fresh recovery';");}}}
#[test]
fn button_form_action_brand_prototype_authority_and_abrupt_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('submit'),P=HTMLButtonElement.prototype,a=Object.getOwnPropertyDescriptor(P,'formAction'),calls=0;for(var bad of [{},document,document.body,document.getElementById('form'),document.getElementById('area'),Object.create(P)]){try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});throw 'brand missing';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls)throw 'brand converted';var marker={};try{x.formAction={toString:function(){x.setAttribute('data-side','kept');throw marker;}};throw 'abrupt missing';}catch(e){if(e!==marker)throw e;}if(x.getAttributeNS(null,'formaction')!==null||x.getAttribute('data-side')!=='kept')throw 'abrupt atomicity';x.formAction={toString:function(){calls++;x.formAction='inner';return 'outer';}};if(calls!==1||x.formAction!=='https://button-action.test/outer')throw 'once conversion';Object.defineProperty(P,'formAction',{get:function(){return 'author';},configurable:true});a.set.call(x,'saved');if(x.formAction!=='author'||a.get.call(x)!=='https://button-action.test/saved')throw 'saved authority';Object.defineProperty(P,'formAction',a);");}
#[test]
fn button_form_action_native_submitter_override_preserves_security(){let(mut d,mut f,mut p)=fixture();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let submit=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("submit")).unwrap();let l=crate::navigation::address("https://button-action.test/source",&crate::navigation::Location::home()).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('submit');x.formAction='next';");let sent=f.submit_request(&d,owner,Some(submit),&l,&l).unwrap();assert_eq!(sent.location.display(),"https://button-action.test/next");let crate::http::Request::FormPost{body,..}=sent.request else{panic!("POST")};assert_eq!(body,b"q=Seed&go=sent");assert_eq!(f.submit_request(&d,owner,None,&l,&l).unwrap().location.display(),"https://button-action.test/default");run(&mut d,&mut f,&mut p,"x.formAction='http://button-action.test/insecure';if(x.formAction!=='http://button-action.test/insecure')throw 'passive reflection';");let before=format!("{:?}",d.nodes);assert!(f.submit_request(&d,owner,Some(submit),&l,&l).err().unwrap().contains("HTTPS form"));assert_eq!(format!("{:?}",d.nodes),before);}
#[test]
fn button_form_action_attribute_writers_keep_identity_observers_and_dirty_editor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('submit'),editor=document.getElementById('area');editor.value='Edited';x.formAction='before';var attribute=x.getAttributeNodeNS(null,'formaction'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for code in ["x.setAttribute('formaction','send');","x.setAttributeNS(null,'formaction','send');","attribute.value='send';","attribute.nodeValue='send';","attribute.textContent='send';"]{p.begin_job();run(&mut d,&mut f,&mut p,"x.formAction='before';watch.takeRecords();");run(&mut d,&mut f,&mut p,code);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.formAction!=='https://button-action.test/send'||x.getAttributeNodeNS(null,'formaction')!==attribute||records.length!==1||records[0].oldValue!=='before'||records[0].attributeName!=='formaction'||editor.value!=='Edited')throw 'attribute observation';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(3,1,2,true));}}
